// Extract sensor data
const sensorType = msg.payload.sensor_type || 'unknown';
const value = parseFloat(msg.payload.value);
const equipmentId = msg.payload.equipment_id;

// Define thresholds
const thresholds = {
    temperature: { warning: 80, critical: 90 },
    vibration: { warning: 5.0, critical: 7.0 },
    pressure: { warning: 8.0, critical: 10.0 },
    energy: { warning: 60, critical: 80 },
    rpm: { warning: 3500, critical: 4000 },
    load: { warning: 85, critical: 95 }
};

const threshold = thresholds[sensorType];

if (!threshold) {
    // Unknown sensor type, pass through as normal
    return [null, msg];
}

let severity = null;
if (value >= threshold.critical) {
    severity = 'critical';
} else if (value >= threshold.warning) {
    severity = 'warning';
}

if (severity) {
    // Create alert message
    const alert = {
        id: `alert_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        equipment_id: equipmentId,
        severity: severity,
        type: sensorType,
        message: `${sensorType.charAt(0).toUpperCase() + sensorType.slice(1)} ${severity} threshold exceeded: ${value}`,
        recommended_action: `Check ${sensorType} sensor and equipment condition`,
        value: value,
        threshold: severity === 'critical' ? threshold.critical : threshold.warning,
        timestamp: new Date().toISOString(),
        source: 'supos_eventflow'
    };

    msg.payload = alert;
    return [msg, null]; // Send to alert output
} else {
    // Normal reading
    return [null, msg]; // Send to normal output
}
